// ==============================================================
// n8n Code Node: Parse TikTok metadata + upload to Supabase Storage
// ==============================================================
// CONFIG — set these to match your Supabase project
const SUPABASE_URL = 'https://ojiaowvkdyoiebgejkxj.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im9qaWFvd3ZrZHlvaWViZ2Vqa3hqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4NTA1NTA3MywiZXhwIjoyMTAwNjMxMDczfQ.0-Cqd4NZIgZejWD_WO-KZla-Xj-PYxlJIqRGFXjB-Aw';
const BUCKET       = 'videos';
// ==============================================================

const https = require('https');
const { URL: UrlClass } = require('url');

// ---- Helpers ---------------------------------------------------

function parseEpisode(title) {
  const cleaned = (title || '').replace(/\s*[—\-–]\s*(♬.*|original sound.*|sonido original.*)$/i, '').trim();
  const patterns = [
    /^(.+?)\s*EP\.?\s*(\d+)/i,
    /^(.+?)\s+[—\-–]\s*(?:Ep|Episode)\s*(\d+)/i,
    /^(.+?)\s+Eps?\s*(\d+)/i,
    /^(.+?)\s+#\s*(\d+)/,
    /^(.+?)\s+Part\s*(\d+)/i,
  ];
  for (const pat of patterns) {
    const m = pat.exec(cleaned);
    if (m) return [m[1].trim().replace(/[.,:; ]+$/, ''), parseInt(m[2], 10)];
  }
  return [cleaned, null];
}

function slugId(name) {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 80) || 'series';
}

function httpsGet(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { followRedirects: true, timeout: 60000 }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        httpsGet(res.headers.location).then(resolve).catch(reject);
        return;
      }
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => resolve(Buffer.concat(chunks)));
      res.on('error', reject);
    }).on('error', reject);
  });
}

function httpsPost(url, data, headers) {
  return new Promise((resolve, reject) => {
    const u = new UrlClass(url);
    const opts = {
      hostname: u.hostname,
      port: u.port || 443,
      path: u.pathname + (u.search || ''),
      method: 'POST',
      headers: { ...headers, 'Content-Length': Buffer.byteLength(data) },
    };
    const req = https.request(opts, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => {
        try { resolve(JSON.parse(Buffer.concat(chunks).toString())); }
        catch { resolve({ raw: Buffer.concat(chunks).toString() }); }
      });
    });
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

// ---- Main -------------------------------------------------------

const input = $input.first().json;

// Flatten: RapidAPI responses vary by provider — normalise
const item = input.data || input;
const title       = item.title || item.desc || '';
const description = item.description || item.desc || title;
const videoUrl    = item.video_url || (item.video && item.video.url) || item.url || '';
const thumbnail   = item.thumbnail || item.cover || item.thumbnail_url || '';
const username    = item.username || item.author || item.unique_id || '';
const duration    = parseInt(item.duration || item.video_duration || '30', 10);

// Parse series title + episode number
let [seriesTitle, episodeNum] = parseEpisode(title);

// Fallback: use @username as series title if parsed title is garbage
if (!seriesTitle || /^(untitled|video|)$/i.test(seriesTitle)) {
  seriesTitle = username ? `@${username}` : 'Untitled';
}

const seriesSlug = slugId(seriesTitle);
const episodeId  = `ep-${seriesSlug}-${episodeNum || 'X'}`;

// ---- Duplicate check: query Supabase episodes table ------------
let alreadyExists = false;
if (episodeNum !== null && episodeNum !== undefined) {
  try {
    const checkUrl = `${SUPABASE_URL}/rest/v1/episodes?id=eq.${encodeURIComponent(episodeId)}&select=id&limit=1`;
    const checkBody = await httpsGet(checkUrl);
    const checkResult = JSON.parse(checkBody.toString());
    alreadyExists = Array.isArray(checkResult) && checkResult.length > 0;
  } catch (e) {
    // If Supabase check fails, assume new so we don't skip
  }
}

// ---- Upload video + thumbnail to Supabase Storage ----------------
let videoStorageUrl  = videoUrl;
let thumbStorageUrl  = thumbnail;

if (!alreadyExists && videoUrl) {
  try {
    // Download video
    const videoBuf = await httpsGet(videoUrl);
    const videoKey = `${seriesSlug}/video_${episodeNum || '0'}.mp4`;
    const uploadResp = await httpsPost(
      `${SUPABASE_URL}/storage/v1/object/${BUCKET}/${videoKey}`,
      videoBuf,
      {
        'Content-Type': 'video/mp4',
        'apikey': SUPABASE_KEY,
        'Authorization': `Bearer ${SUPABASE_KEY}`,
      }
    );
    videoStorageUrl = `${SUPABASE_URL}/storage/v1/object/public/${BUCKET}/${videoKey}`;

    // Download + upload thumbnail if available
    if (thumbnail) {
      const thumbBuf = await httpsGet(thumbnail);
      const ext = thumbnail.match(/\.(png|jpe?g|webp)/i)?.[1]?.replace(/jpe?g/, 'jpg') || 'jpg';
      const thumbKey = `${seriesSlug}/thumb_${episodeNum || '0'}.${ext}`;
      await httpsPost(
        `${SUPABASE_URL}/storage/v1/object/${BUCKET}/${thumbKey}`,
        thumbBuf,
        {
          'Content-Type': `image/${ext === 'jpg' ? 'jpeg' : ext}`,
          'apikey': SUPABASE_KEY,
          'Authorization': `Bearer ${SUPABASE_KEY}`,
        }
      );
      thumbStorageUrl = `${SUPABASE_URL}/storage/v1/object/public/${BUCKET}/${thumbKey}`;
    }
  } catch (e) {
    // Fallback: keep original URLs
  }
}

// ---- Return -----------------------------------------------------
return [{
  json: {
    // Original metadata
    webpage_url:   item.webpage_url || item.url || '',
    title:         title,
    description:   description,
    duration:      Math.max(1, Math.ceil(duration / 60)),
    username:      username,
    // Parsed series / episode
    series_title:   seriesTitle,
    series_slug:    seriesSlug,
    episode_number: episodeNum,
    episode_id:     episodeId,
    // Storage URLs (either Supabase or original)
    video_url:      videoStorageUrl,
    thumbnail_url:  thumbStorageUrl,
    // Dup flag for IF node
    already_exists: alreadyExists,
  }
}];
